import{_ as t,o,c as r,aa as i}from"./chunks/framework.BAs_AphD.js";const m=JSON.parse('{"title":"Loading the Budget","description":"","frontmatter":{"title":"Loading the Budget","wiki":"en:performedworks:budget"},"headers":[],"relativePath":"en/performedworks/budget.md","filePath":"en/performedworks/budget.md","lastUpdated":1794388980000}'),a={name:"en/performedworks/budget.md"};function n(s,e,d,l,u,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="loading-the-budget" tabindex="-1">Loading the Budget <a class="header-anchor" href="#loading-the-budget" aria-label="Permalink to &quot;Loading the Budget&quot;">​</a></h1><p>In order to use Performed Works in Buildary, the current project budget must first be loaded.</p><p>It is common for the budget to change throughout the course of a project. New items may be added, while the quantities, prices, or any other information of existing items may be changed. Therefore, the budget can be imported into Buildary repeatedly. Existing data is only updated, and previously entered Performed Works are not lost.</p><h2 id="where-the-budget-can-be-loaded-from" tabindex="-1">Where the Budget Can Be Loaded from <a class="header-anchor" href="#where-the-budget-can-be-loaded-from" aria-label="Permalink to &quot;Where the Budget Can Be Loaded from&quot;">​</a></h2><p><strong>Buildary supports input from various sources. However, only one of the inputs listed below may be used for each project. Different inputs cannot be combined within a single project.</strong></p><p><strong>1. RSV – Construction Production Management</strong></p><p>An information system designed for construction companies, developed by First information systems, s.r.o. RSV is directly integrated with Buildary. It uses web services and the API provided by Buildary to transfer data. RSV includes buttons for creating a project and transferring budgets to Buildary. This is an exceptionally simple solution from a user perspective.</p><p><strong>2. MS Excel</strong></p><p>Currently the most widely used software on construction projects for creating budgets as well as Performed Works. A budget in MS Excel can be adjusted to the required format and then imported into Buildary. In the future, a module will be available that will allow budgets to be imported from Excel in any format.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Save the imported file carefully. If you need to make any changes to the budget, modify the quantities of existing items, or add or delete items, always edit only this file and then import it into Buildary again. It is essential that the items have the same IDs during subsequent imports as they did during the initial import. Otherwise, repeated imports may completely corrupt your data.</p></div><p><strong>3. Kros4</strong></p><p>The budget can also be imported from Kros4 version 2024 or later, which is designed for creating budgets and cost calculations for construction work.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Always perform subsequent budget imports from the same project from which you originally imported the budget into Buildary. If you need to make any changes to the budget, modify the quantities of existing items, or add or delete items, always make the changes in this original project in KROS and then import it into Buildary again. If you import a different project (for example, a copy of the original), the repeated import will completely corrupt your data.</p></div><p><strong>4. Cost Estimating Software</strong></p><p>We are preparing integrations with several commonly used cost estimating applications from ÚRS, Callida, and RTS.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Combining Data Sources</strong></p><p>Different budget import sources <strong>CANNOT</strong> be combined within a single project. If you initially upload a budget from Excel, you cannot subsequently import one from KROS, as this would result in the original budget being completely overwritten with new data.</p></div>',16)])])}const g=t(a,[["render",n]]);export{m as __pageData,g as default};
